/* Interactive gift effects; all game mutations go through the supplied hooks. */
class CowEffects {
 constructor({core,getState,getCows,collect,launch,save,toast,sound,reduced,canRun=()=>true}){
  Object.assign(this,{core,getState,getCows,collect,launch,save,toast,sound,reduced,canRun});
  this.cfg={collectCount:10,tornadoSeconds:8,tornadoRadius:180,boomSeconds:30,rules:[]};this.nextCollect=0;this.lastCount='';
  try{const old=JSON.parse(localStorage.getItem('pet-catch-effects-v1')||'null');if(old){for(const[k,min,max]of this.bounds())if(Number.isInteger(old[k])&&old[k]>=min&&old[k]<=max)this.cfg[k]=old[k];if(Array.isArray(old.rules))this.cfg.rules=old.rules.slice(0,100).filter(r=>r&&typeof r.id==='string'&&typeof r.name==='string'&&['recall','tornado','boom'].includes(r.kind)&&Number.isInteger(r.value)&&r.value>=1&&r.value<=this.limit(r.kind)).map(r=>({id:r.id,name:r.name.slice(0,40),kind:r.kind,value:r.value,enabled:r.enabled!==false}));}}catch{this.toast('互动规则读取失败，本页先使用默认值，原记录保留');}
  this.bind();this.renderRules();for(const[k]of this.bounds())document.getElementById(k).value=this.cfg[k];
 }
 bounds(){return[['collectCount',1,10000],['tornadoSeconds',1,300],['tornadoRadius',60,320],['boomSeconds',1,300]];}
 limit(kind){return kind==='recall'?10000:300;}
 nameKey(name){return String(name).normalize('NFKC').trim().toLocaleLowerCase();}
 ruleFor(name){const key=this.nameKey(name);return this.cfg.rules.find(r=>r.enabled&&r.name.trim()&&this.nameKey(r.name)===key);}
 saveConfig(){try{localStorage.setItem('pet-catch-effects-v1',JSON.stringify(this.cfg));}catch{this.toast('互动设置未能保存，本页暂时生效');}}
 trigger(kind,value,multiplier=1){if(!this.canRun()){this.toast('素材正在加载，请稍后');return 0;}if(!['recall','tornado','boom'].includes(kind)||!Number.isInteger(value)||value<1||value>this.limit(kind)||!Number.isSafeInteger(multiplier)||multiplier<1)return 0;const state=this.getState();let n=0;
  if(kind==='recall'){const list=this.getCows().filter(c=>!c.dead&&!c.held).slice(0,Math.min(10000,value*multiplier));n=this.collect(list,true)||0;if(n)this.sound('recall');this.toast(`召回 ${n} 只萌宠`);}
  if(kind==='tornado'){this.core.extendTornado(state,Math.min(300,value*multiplier));this.save();this.sound('tornado');this.toast('龙卷风已开启，移动鼠标吸走附近萌宠');}
  if(kind==='boom'){const before=new Set(this.getCows().map(c=>c.id));const kinds=this.core.burst(state,value);n=kinds.length;this.launch(before);this.save();this.boomFlash();this.sound('boom');this.toast(n?`小窝一震，${n} 只萌宠跑出来啦`:`最近 ${value} 秒没有可跑出的萌宠`);}
  return n;
 }
 gift(name,count){if(!this.canRun())return false;const r=this.ruleFor(name);if(!r)return false;this.trigger(r.kind,r.value,count);return true;}
 stopWind(){this.getState().tornadoUntil=0;this.save();this.update(Date.now());this.toast('龙卷风已停止');}
 bind(){const $=id=>document.getElementById(id);
  for(const[k,min,max]of this.bounds())$(k).addEventListener('input',()=>{const v=Number($(k).value);if(!$(k).value.trim()||!Number.isInteger(v)||v<min||v>max){$('effects-error').textContent=`请输入 ${min}–${max} 的整数；未应用。`;return;}this.cfg[k]=v;this.saveConfig();$('effects-error').textContent='';});
  $('recall-now').onclick=()=>this.trigger('recall',this.cfg.collectCount);$('tornado-now').onclick=()=>this.trigger('tornado',this.cfg.tornadoSeconds);$('boom-now').onclick=()=>this.trigger('boom',this.cfg.boomSeconds);$('stop-tornado').onclick=()=>this.stopWind();
  $('add-effect-rule').onclick=()=>{if(this.cfg.rules.length>=100){this.toast('最多设置100条互动规则');return;}this.cfg.rules.push({id:'effect-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),name:'',kind:'recall',value:10,enabled:true});this.saveConfig();this.renderRules();};
  document.addEventListener('pointermove',e=>{if(e.target.closest('#settings,#toolbar,#top,#pen,.float-hud')||e.isPrimary===false)return;this.getState().tornadoPos={x:Math.max(0,Math.min(1,e.clientX/innerWidth)),y:Math.max(0,Math.min(1,e.clientY/innerHeight))};});
 }
 renderRules(){const box=document.getElementById('effect-rules');box.replaceChildren();for(const r of this.cfg.rules){const row=document.createElement('div');row.className='effect-rule';row.dataset.effectRule=r.id;const enabled=document.createElement('input');enabled.type='checkbox';enabled.checked=r.enabled;enabled.setAttribute('aria-label','启用互动规则');enabled.onchange=()=>{r.enabled=enabled.checked;this.saveConfig();};const name=document.createElement('input');name.type='text';name.maxLength=40;name.placeholder='礼物名称';name.value=r.name;name.setAttribute('aria-label','互动礼物名称');name.oninput=()=>{const v=name.value.trim(),key=this.nameKey(v);if(key&&this.cfg.rules.some(x=>x!==r&&this.nameKey(x.name)===key)){name.setAttribute('aria-invalid','true');document.getElementById('effects-error').textContent='同一个礼物只能配置一条互动规则';return;}r.name=v;name.removeAttribute('aria-invalid');document.getElementById('effects-error').textContent='';this.saveConfig();};name.onblur=()=>{if(name.hasAttribute('aria-invalid')){name.value=r.name;name.removeAttribute('aria-invalid');}};const kind=document.createElement('select');for(const[value,label]of[['recall','召回萌宠'],['tornado','龙卷风'],['boom','小窝爆炸']])kind.add(new Option(label,value));kind.value=r.kind;kind.setAttribute('aria-label','互动效果');const value=document.createElement('input');value.type='number';value.min=1;value.max=this.limit(r.kind);value.value=r.value;value.setAttribute('aria-label','互动规则数值');const unit=document.createElement('span');unit.textContent=r.kind==='recall'?'只':'秒';kind.onchange=()=>{r.kind=kind.value;r.value=Math.min(r.value,this.limit(r.kind));value.max=this.limit(r.kind);value.value=r.value;unit.textContent=r.kind==='recall'?'只':'秒';this.saveConfig();};value.oninput=()=>{const v=Number(value.value);if(!value.value.trim()||!Number.isInteger(v)||v<1||v>this.limit(r.kind)){value.setAttribute('aria-invalid','true');return;}r.value=v;value.removeAttribute('aria-invalid');this.saveConfig();};value.onblur=()=>{if(value.hasAttribute('aria-invalid')){value.value=r.value;value.removeAttribute('aria-invalid');this.toast('规则数值无效，保留原设置');}};const test=document.createElement('button');test.textContent='测试';test.onclick=()=>this.trigger(r.kind,r.value);const remove=document.createElement('button');remove.textContent='删除';remove.onclick=()=>{this.cfg.rules=this.cfg.rules.filter(x=>x!==r);this.saveConfig();this.renderRules();};row.append(enabled,name,kind,value,unit,test,remove);box.append(row);}if(!this.cfg.rules.length){const p=document.createElement('p');p.textContent='还没有绑定互动礼物，可先用上方按钮试玩。';box.append(p);}}
 update(now){const s=this.getState(),until=s.tornadoUntil||0,active=until>now,fx=document.getElementById('tornado-fx');fx.hidden=!active;const status=document.getElementById('wind-status');if(!active){this.lastCount='';if(status.textContent!=='未开启')status.textContent='未开启';return;}const pos=s.tornadoPos||{x:.45,y:.65},x=pos.x*innerWidth,y=pos.y*innerHeight,r=this.cfg.tornadoRadius;fx.style.left=x+'px';fx.style.top=y+'px';fx.style.width=r*2+'px';fx.style.height=r*2+'px';const count=Math.ceil((until-now)/1000)+' 秒';if(count!==this.lastCount){document.getElementById('tornado-countdown').textContent='龙卷风 · '+count;status.textContent='剩余 '+count;this.lastCount=count;}if(now<this.nextCollect)return;this.nextCollect=now+170;const c=this.getCows().filter(c=>!c.dead&&!c.held&&Math.hypot(c.x-x,c.y-y)<r).sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0];if(c)this.collect([c],true);}
 boomFlash(){const pen=document.getElementById('pen'),b=pen.getBoundingClientRect(),fx=document.getElementById('boom-fx');clearTimeout(this.boomTimer);fx.hidden=false;fx.style.left=(b.left+b.width/2)+'px';fx.style.top=(b.top+b.height*.6)+'px';fx.classList.remove('burst');pen.classList.remove('booming');void fx.offsetWidth;fx.classList.add('burst');pen.classList.add('booming');this.boomTimer=setTimeout(()=>{fx.hidden=true;pen.classList.remove('booming');},850);}
}
